package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamEconomyBank2 {
  private const val T = "බෞද්ධ ආර්ථික දර්ශනය හා පරිසර සංරක්ෂණය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("සිඟාලෝවාද සූත්‍රයේ දැක්වෙන පරිදි ධනය විනාශ කරන 'භෝග විනාශ මුඛ හයට' අයත් නොවන්නේ කුමක්ද?", "දැහැමින් ධනය ඉපයීම", "සුරාපානය කිරීම", "සූදු ක්‍රීඩාව", "අකාලයේ ගම් නගරවල සංචාරය", "ධාර්මිකව ධනය ඉපයීම දියුණුවට හේතු වන අතර ඉහත අනෙක් ඒවා විනාශයකි."),
    q("භෝග විනාශ මුඛයක් වන 'අක්ඛධුත්තය' (සූදු කෙළීම) නිසා පුද්ගලයාට සිදුවන ප්‍රධාන හානිය කුමක්ද?", "දිනකදී සියලු ධනය නැති වී සමාජ අපකීර්තියට පත්වීම", "ශරීර සෞඛ්‍යය වැඩි වීම", "මිතුරන් වැඩි වීම", "නුවණ වැඩීම", "සූදුවෙන් දිනන අය වෛර බඳින අතර පරාජිතයා ධනය නැති වී දුක් වෙයි."),
    q("භෝග විනාශ මුඛයක් ලෙස දැක්වෙන 'සමජ්ජාභිචරණය' යනු කුමක්ද?", "නැටුම්, ගැයුම් හා විසුළු දසුන් නැරඹීමට නිරන්තරයෙන් යාම", "දහම් දෙසීමට යාම", "ගොවිතැන් කිරීම", "වෙළඳාම් කිරීම", "සැණකෙළි පසුපස හඹා යෑමෙන් කාලය හා ධනය නාස්ති වේ."),
    q("පරිසර සංරක්ෂණය අරමුණින් ගස් වැල් රැකීම හා වැව් අමුණු තැනීම උතුම් පුණ්‍ය ක්‍රියාවක් බව වනරෝප සූත්‍රයේ උගන්වන්නේ කුමක් සඳහාද?", "මිනිසුන්ට හා සතුන්ට සෙවණ හා ජලය සලසා සෙත සැලසීමට", "වනාන්තර විනාශ කිරීමට", "ගැටුම් ඇති කිරීමට", "කාලය නාස්ති කිරීමට", "ගස් සිටුවීම, පැන් හල් තැනීම සදාකාලික පින් වැඩෙන ක්‍රියා වේ."),
    q("බුදුරදුන් වදාළ 'මීමැස්සා මලට හානියක් නොකර මීපැණි ගන්නා අයුරින්' ධනය ඉපයීමෙන් අදහස් කරන්නේ කුමක්ද?", "පරිසරයට හා අනුන්ට පීඩා නොකර ධාර්මිකව ධනය සෙවීම", "සතුන්ට හිංසා කිරීම", "පරිසරය ගිනි තැබීම", "අධික බදු අය කිරීම", "සොබාදහමට හා සමාජයට හානි නොකරන සාධාරණ ආර්ථික ප්‍රතිපත්තියයි."),
    q("බෞද්ධ ආර්ථික දර්ශනයට අනුව නිෂ්පාදන ක්‍රියාවලියේදී පාරිසරික සමතුලිතතාව ආරක්ෂා කිරීමට වැදගත් වන ප්‍රතිපත්තිය කුමක්ද?", "අල්පේච්ඡතාව හා සීමිත පරිභෝජනය", "අසීමිත පරිභෝජනවාදය", "සම්පත් සියල්ල එකවර වැය කිරීම", "පරිසරය දූෂණය කිරීම", "අවශ්‍යතාවට වඩා ආශාවන් පසුපස නොයාම පරිසරය රකියි."),
    q("බෞද්ධ සමාජයේ පරිසර හිතකාමී සංකල්පයක් වන 'අභයදානය' මගින් ප්‍රධාන වශයෙන් ආරක්ෂා කෙරෙන්නේ කුමක්ද?", "සත්ව ජීවිත හා පරිසරයේ ජීවී විවිධත්වය", "ගොඩනැගිලි සංරක්ෂණය", "පුරාවස්තු", "රන් රිදී භාණ්ඩ", "සතුන්ට මරණ බියෙන් තොරව ජීවත් වීමට ඉඩ සැලසීම අභයදානයයි."),
    q("බුදුරදුන් වදාළ 'අනාවෘත ධර්ම' අතර සොබාදහමේ අසිරිමත් ක්‍රියාකාරීත්වය පාලනය වන ස්වභාවික නියාමය කුමක්ද?", "උතු නියාමය", "බීජ නියාමය", "කම්ම නියාමය", "චිත්ත නියාමය", "ඍතු වෙනස්වීම්, වැසි ඇතිවීම ආදිය උතු නියාමයට අයත් වේ."),
    q("බුදුදහම උගන්වන පරිදි මිනිසා හා සොබාදහම අතර තිබිය යුතු සැබෑ සබැඳියාව කුමක්ද?", "අන්‍යෝන්‍ය අවබෝධයෙන් හා ගෞරවයෙන් යුතුව සහජීවනයෙන් සිටීම", "සොබාදහම සම්පූර්ණයෙන් පාලනය කර විනාශ කිරීම", "ස්වභාවධර්මයෙන් පලා යාම", "ගස් කපා නගර සෑදීම", "මිනිසා ස්වභාවධර්මයේ කොටස්කරුවෙකු මිළු හිමිකරුවා නොවේ."),
    q("පරිසර සංරක්ෂණයේදී ගස් කැපීමෙන් වැළකී සිටීමට භික්ෂූන්ට පනවා ඇති විනය ශික්ෂාව කුමක්ද?", "භූතගාම හා හරුතගාම සික්ඛාපදය", "මුසාවාද සික්ඛාපදය", "අදත්තාදාන සික්ඛාපදය", "සුරාමේරය සික්ඛාපදය", "පැළ වූ ගස් හා තෘණ විනාශ කිරීම පැවිදි උතුමන්ට තහනම්ය."),
    q("බුදුරදුන්ගේ පරිසර හිතකාමී දැක්ම අනුව හිමාල වනාන්තරයේ සතුන් සමඟ වැඩසවසන ලද අවස්ථා දැක්වෙන ග්‍රන්ථය කුමක්ද?", "ජාතක පාලිය (පන්සිය පනස් ජාතකය)", "අභිධර්මය", "විනය පිටකය", "පරිවාර පාලිය", "බෝසතාණන් වහන්සේ බොහෝ ජාතකවල වෘක්ෂ දේවතාවුන් ලෙස හා තාපසයන් ලෙස පරිසරය රැක ඇත."),
    q("බෞද්ධ ආර්ථික ක්‍රමයේදී ණය ගැනීමෙන් වැළකී සිටීම උතුම් සුවයක් ලෙස දැක්වෙන සූත්‍රය කුමක්ද?", "අණණ සූත්‍රය", "පරාභව සූත්‍රය", "වසල සූත්‍රය", "රතන සූත්‍රය", "අණණ සුඛ හෙවත් ණය නැති සතුට ගිහියෙකුට මහා මානසික නිදහසකි."),
    q("පැරණි සිංහල බෞද්ධ සමාජයේ 'ගමයි, පන්සලයි, වැවයි, දාගැබයි' යන සංකල්පයෙන් තහවුරු වූ ප්‍රධාන කරුණ කුමක්ද?", "ආගමික, සමාජීය හා පාරිසරික සමතුලිතතාව ආරක්ෂා වීම", "ගම් අතර යුද්ධ ඇති වීම", "වනාන්තර විනාශ වීම", "ජල සම්පත සිඳී යාම", "වැව් අමුණු හා පන්සල මගින් ගමේ පරිසරය හා සංස්කෘතිය රැකුණි."),
    q("බෞද්ධ ආර්ථික මූලධර්මවලට අනුව කෙනෙකු ධනය රැස් කිරීමේදී අනුගමනය කළ යුතු නිවැරදි මාවත කුමක්ද?", "දහඩිය මහන්සියෙන් දැහැමින් උපයා ගැනීම", "සොරකම් කිරීම", "අනුන් රැවටීම", "අල්ලස් ලබා ගැනීම", "උට්ඨාන විරියෙන් හා දැහැමි රැකියාවෙන් ධනය සෙවිය යුතුය."),
    q("බුදුරදුන් වදාළ 'අප්පිච්ඡතා' (අල්පේච්ඡතාව) ගුණය ආර්ථික පරිභෝජනයට අදාළ වන්නේ කෙසේද?", "අනවශ්‍ය ද්‍රව්‍ය මිලදී ගැනීමෙන් වැළකී සරලව ජීවත් වීම", "කිසිදු ආහාරයක් නොගෙන සිටීම", "නිවෙස්වලින් බැහැර වීම", "ධනය පස්වල වළ දැමීම", "අනවශ්‍ය වියම් අඩු කර ගැනීමෙන් පාරිසරික සම්පත් නාස්තිය වළකී."),
    q("සොබාදහමට ගරු කරමින් ගස් වැල් රැකීමෙන් ලැබෙන පාරිසරික ප්‍රතිලාභය කුමක්ද?", "පිරිසිදු වාතය, වැසි ලැබීම හා පස ආරක්ෂා වීම", "ප්‍රදේශය අඳුරු වීම", "උෂ්ණත්වය වැඩි වීම", "ජලය සිඳී යාම", "ගස් වැල් මගින් පරිසරයේ සමතුලිතතාව හා ඔක්සිජන් රැකේ."),
    q("බෞද්ධ ආර්ථික දර්ශනයේ 'පරිභෝජන සංයමය' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "අධික පරිභෝජනයෙන් තොරව සීමිතව හා ප්‍රයෝජනවත් ලෙස පාරිභෝජනය", "සියලු දේ පරිභෝජනය කිරීම", "කිසිවක් නොකා සිටීම", "ආහාර විනාශ කිරීම", "සම්පත් නාස්ති නොකර මධ්‍යම ප්‍රතිපදාවෙන් පරිභෝජනය කිරීමයි."),
    q("පරිසර සංරක්ෂණය අරමුණින් ගස් සිටුවීම හා දිය නාන තොටුපළවල් සෑදීම කුමන පුණ්‍ය කර්මයක් ලෙස දැක්ේද?", "සදාකාලික පින් ලැබෙන මහජන සේවයක් ලෙස", "තාවකාලික ක්‍රියාවක් ලෙස", "පවක් ලෙස", "නිර්වාණයට බාධාවක් ලෙස", "ආරාම රෝපා වන රෝපා සූත්‍රයට අනුව මේවා නිරන්තර පින් ගෙන දේ."),
    q("බෞද්ධ ආර්ථික චින්තනයට අනුව 'ශ්‍රමයේ ගෞරවය' ආරක්ෂා වන ආකාරය කුමක්ද?", "ඕනෑම දැහැමි වෘත්තියක් හෝ ශ්‍රමදානය උසස් ලෙස සැලකීම", "ශ්‍රමිකයන් පහත් කොට සැලකීම", "වැටුප් නොදී වැඩ ගැනීම", "කම්කරුවන් සූරා කෑම", "කුමන කර්මාන්තයක් වුවද දැහැමි නම් එය ගෞරවනීය වේ."),
    q("බුදුරදුන්ගේ ජීවිතය හා සම්බන්ධ වූ පරිසර පද්ධතිවලින් ප්‍රධානම ස්ථානයක් හිමි වන්නේ කුමන පරිසරයටද?", "වනාන්තර හා වනස්පති වෘක්ෂ මූලවලට", "මහල් මාලිගාවලට", "කාන්තාරවලට", "විශාල නගරවලට", "උපතේ සිට පිරිනිවන් පෑම දක්වා උන්වහන්සේ වැඩි කාලයක් ගත කළේ වන සෙනසුන්වලය.")
  )
}
